function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  Object.freeze(value);
  for (const child of Object.values(value)) deepFreeze(child);
  return value;
}

function registryEntry(entry) {
  return deepFreeze({
    version: '1.0.0',
    deterministic: true,
    workerSafe: true,
    shaderSafe: false,
    lossy: false,
    wgslMirrorId: null,
    tests: Object.freeze([]),
    tags: Object.freeze([]),
    ...entry,
    computeOperationIds: listComputeOperations({ moduleId: entry.moduleId || entry.id })
      .filter(operation => entry.kind === 'module' || operation.cpuExports.includes(entry.cpuExport)).map(operation => operation.id),
  });
}

